        /// The `CHNL1_INT_RAW` register.
        ///
        /// Raw interrupt status
        pub mod chnl1_int_raw {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x00000001;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x5c;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// This interrupt raw bit turns to high level when the counter approach to reg_out_len.
                #[inline]
                pub const fn chnl1_outcnt_eof_int_raw(self) -> bool {
                    (self.0 & 0x00000001) != 0
                }
            }

            /// One sample of the register's asserted fields, to acknowledge once.
            #[must_use = "a sampled write-one-to-clear set must be acknowledged"]
            #[derive(Debug, Eq, PartialEq)]
            pub struct Snapshot(pub(super) u32);

            impl Snapshot {
                /// Whether no declared field was asserted.
                pub const fn is_clear(&self) -> bool {
                    self.0 == 0
                }

                /// This interrupt raw bit turns to high level when the counter approach to reg_out_len.
                #[inline]
                pub const fn chnl1_outcnt_eof_int_raw(&self) -> bool {
                    (self.0 & 0x00000001) != 0
                }

                /// The snapshot without `CHNL1_OUTCNT_EOF_INT_RAW` unless `keep`: it is then not acknowledged.
                pub const fn retain_chnl1_outcnt_eof_int_raw(self, keep: bool) -> Self {
                    if keep {
                        self
                    } else {
                        Self(self.0 & !0x00000001)
                    }
                }
            }
        }

