        /// The `SYS` register.
        ///
        /// Control and configuration registers
        pub mod sys {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x80000001;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0xf8;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// write this bit to set the bitscrambler tx loop back to DMA rx
                #[inline]
                pub const fn loop_mode(self) -> bool {
                    (self.0 & 0x00000001) != 0
                }

                /// Write this bit to enable the configuration register clock to be always-on. 0: turn on during access, 1: always-on.
                #[inline]
                pub const fn clk_en(self) -> bool {
                    (self.0 & 0x80000000) != 0
                }
            }

            /// The register's value while it is changed.
            pub struct W(pub(super) u32);

            impl W {
                /// write this bit to set the bitscrambler tx loop back to DMA rx
                #[inline]
                pub const fn loop_mode(&self) -> bool {
                    (self.0 & 0x00000001) != 0
                }

                /// Write this bit to enable the configuration register clock to be always-on. 0: turn on during access, 1: always-on.
                #[inline]
                pub const fn clk_en(&self) -> bool {
                    (self.0 & 0x80000000) != 0
                }

                /// Set `LOOP_MODE`.
                #[inline]
                pub fn set_loop_mode(&mut self, value: bool) -> &mut Self {
                    self.0 = (self.0 & !0x00000001) | u32::from(value);
                    self
                }

                /// Set `CLK_EN`.
                #[inline]
                pub fn set_clk_en(&mut self, value: bool) -> &mut Self {
                    self.0 = (self.0 & !0x80000000) | (u32::from(value) << 31);
                    self
                }
            }
        }
