        pub type Claim = oer_mmio::Block<oer_mmio::Fixed<0x2c000000>, BlockWords>;

        /// The exclusive owner of the `CACHE` registers.
        #[must_use = "dropping a register owner permanently loses its register authority"]
        pub struct Cache<P: oer_mmio::Placement = oer_mmio::Fixed<0x2c000000>>(
            oer_mmio::Block<P, BlockWords>,
        );

        impl Cache {
            /// The owner of the block's device registers.
            pub const fn new(block: Claim) -> Self {
                Self(block)
            }
        }

        impl<'a> Cache<oer_mmio::Host<'a>> {
            /// The block over host memory, for tests of its accessors.
            pub fn host(words: &'a mut [u32]) -> Result<Self, oer_mmio::HostTooSmall> {
                oer_mmio::Block::host(words).map(Self)
            }
        }

