            pub fn modify_pdma_timer_cfg(&mut self, change: impl FnOnce(&mut pdma_timer_cfg::W)) {
                let mut value = pdma_timer_cfg::W(self.0.read::<0xc>());
                change(&mut value);
                self.0.write::<0xc>(value.0);
            }

