        /// The `RD_REPEAT_DATA0` register.
        ///
        /// Represents rd_repeat_data
        pub mod rd_repeat_data0 {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x0fdffc7f;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x30;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Represents whether reading of individual eFuse block(block4~block9) is disabled or enabled.\\ 1: disabled\\ 0: enabled\\
                #[inline]
                pub const fn rd_dis(self) -> oer_mmio::Bits<7> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// Represents whether the function of usb switch to jtag is disabled or enabled.\\ 1: disabled\\ 0: enabled\\
                #[inline]
                pub const fn dis_usb_jtag(self) -> bool {
                    (self.0 & 0x00000400) != 0
                }

                /// Represents whether USB-Serial-JTAG is disabled or enabled.\\ 1: disabled\\ 0: enabled\\
                #[inline]
                pub const fn dis_usb_serial_jtag(self) -> bool {
                    (self.0 & 0x00000800) != 0
                }

                /// Represents whether the function that forces chip into download mode is disabled or enabled.\\ 1: disabled\\ 0: enabled\\
                #[inline]
                pub const fn dis_force_download(self) -> bool {
                    (self.0 & 0x00001000) != 0
                }

                /// Represents whether SPI0 controller during boot_mode_download is disabled or enabled.\\ 1: disabled\\ 0: enabled\\
                #[inline]
                pub const fn spi_download_mspi_dis(self) -> bool {
                    (self.0 & 0x00002000) != 0
                }

                /// Represents whether TWAI function is disabled or enabled.\\ 1: disabled\\ 0: enabled\\
                #[inline]
                pub const fn dis_twai(self) -> bool {
                    (self.0 & 0x00004000) != 0
                }

                /// Represents whether the selection between usb_to_jtag and pad_to_jtag through strapping gpio15 when both EFUSE_DIS_PAD_JTAG and EFUSE_DIS_USB_JTAG are equal to 0 is enabled or disabled.\\ 1: enabled\\ 0: disabled\\
                #[inline]
                pub const fn jtag_sel_enable(self) -> bool {
                    (self.0 & 0x00008000) != 0
                }

                /// Represents whether JTAG is disabled in soft way.\\ Odd number: disabled\\ Even number: enabled\\
                #[inline]
                pub const fn soft_dis_jtag(self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0 >> 16)
                }

                /// Represents whether JTAG is disabled in the hard way(permanently).\\ 1: disabled\\ 0: enabled\\
                #[inline]
                pub const fn dis_pad_jtag(self) -> bool {
                    (self.0 & 0x00080000) != 0
                }

                /// Represents whether flash encrypt function is disabled or enabled(except in SPI boot mode).\\ 1: disabled\\ 0: enabled\\
                #[inline]
                pub const fn dis_download_manual_encrypt(self) -> bool {
                    (self.0 & 0x00100000) != 0
                }

                /// Represents thether the WIFI6 feature is enable or disabled. 1: WIFI6 is disable, 0: WIFI6 is enabled.
                #[inline]
                pub const fn dis_wifi6(self) -> bool {
                    (self.0 & 0x00400000) != 0
                }

                /// Represents the control of validation of HUK generate mode. Odd of 1 is invalid, even of 1 is valid.
                #[inline]
                pub const fn huk_gen_state(self) -> oer_mmio::Bits<5> {
                    oer_mmio::Bits::truncate(self.0 >> 23)
                }
            }
        }

        /// The `RD_REPEAT_DATA1` register.
        ///
        /// Represents rd_repeat_data
        pub mod rd_repeat_data1 {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x07fffffd;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x34;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Represents the control of key manager random number switch cycle. 0: control by register. 1: 8 km clk cycles. 2: 16 km cycles. 3: 32 km cycles
                #[inline]
                pub const fn km_rnd_switch_cycle(self) -> bool {
                    (self.0 & 0x00000001) != 0
                }

                /// Represents whether the deploy mode of key manager is disable or not. \\ 1: disabled \\ 0: enabled.\\ bit 0: ecsda, bit 1: flash & spi boot srambler, bit2: hmac & aes, bit3: ds & rma nonce, bit4: psram
                #[inline]
                pub const fn km_disable_deploy_mode(self) -> oer_mmio::Bits<5> {
                    oer_mmio::Bits::truncate(self.0 >> 2)
                }

                /// Represents whether corresponding key can only be deployed once. 1 is true, 0 is false. \\ 0: ecsda\\ 1: flash & spi boot srambler\\ 2: hmac & aes\\ 3: ds & rma nonce\\ 4: psram\\
                #[inline]
                pub const fn km_deploy_only_once(self) -> oer_mmio::Bits<5> {
                    oer_mmio::Bits::truncate(self.0 >> 7)
                }

                /// Represents whether corresponding key must come from key manager. 1 is true, 0 is false.\\ 0: ecsda\\ 1: flash\\ 2: reserved\\ 3: reserved\\ 4: psram\\
                #[inline]
                pub const fn force_use_key_manager_key(self) -> oer_mmio::Bits<5> {
                    oer_mmio::Bits::truncate(self.0 >> 12)
                }

                /// Represents whether to disable software written init key, and force use efuse_init_key.
                #[inline]
                pub const fn force_disable_sw_init_key(self) -> bool {
                    (self.0 & 0x00020000) != 0
                }

                /// Represents whether to configure flash encryption use xts-128 key. else use xts-256 key. \\ 0: 128-bit key \\ 1: 256-bit key\\
                #[inline]
                pub const fn km_xts_key_length_256(self) -> bool {
                    (self.0 & 0x00040000) != 0
                }

                /// Represents the threshold level of the RTC watchdog STG0 timeout.\\0: Original threshold configuration value of STG0 *2 \\1: Original threshold configuration value of STG0 *4 \\2: Original threshold configuration value of STG0 *8 \\3: Original threshold configuration value of STG0 *16 \\
                #[inline]
                pub const fn wdt_delay_sel(self) -> bool {
                    (self.0 & 0x00080000) != 0
                }

                /// Represents whether to disable all the SM crypto functions, including SM2, SM3.\\ 1: disabled\\ 0: enabled\\
                #[inline]
                pub const fn dis_sm_crypt(self) -> bool {
                    (self.0 & 0x00100000) != 0
                }

                /// Represents whether SPI boot encrypt/decrypt is disabled or enabled.\\ Odd number of 1: enabled\\ Even number of 1: disabled\\
                #[inline]
                pub const fn spi_boot_crypt_cnt(self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0 >> 21)
                }

                /// Represents whether revoking first secure boot key is enabled or disabled.\\ 1: enabled\\ 0: disabled\\
                #[inline]
                pub const fn secure_boot_key_revoke0(self) -> bool {
                    (self.0 & 0x01000000) != 0
                }

                /// Represents whether revoking second secure boot key is enabled or disabled.\\ 1: enabled\\ 0: disabled\\
                #[inline]
                pub const fn secure_boot_key_revoke1(self) -> bool {
                    (self.0 & 0x02000000) != 0
                }

                /// Represents whether revoking third secure boot key is enabled or disabled.\\ 1: enabled\\ 0: disabled\\
                #[inline]
                pub const fn secure_boot_key_revoke2(self) -> bool {
                    (self.0 & 0x04000000) != 0
                }
            }
        }

