            pub struct R(pub(super) u32);

            impl R {
                /// Configures the output value of GPIO0 ~ 31 output in simple GPIO output mode.\\ 0: Low level\\ 1: High level\\ The value of bit0 ~ bit31 correspond to the output value of GPIO0 ~ GPIO31 respectively. Bitxx ~ bitxx is invalid.\\
                #[inline]
                pub const fn data_orig(self) -> u32 {
                    self.0
                }
            }
