            pub fn read_timeout_limit(&self) -> timeout_limit::R {
                timeout_limit::R(self.0.read::<0x70>())
            }

            /// Read `TIMEOUT_LIMIT`, change fields and write it back; every other bit keeps
            /// the value read.
            #[inline]
            pub fn modify_timeout_limit(&mut self, change: impl FnOnce(&mut timeout_limit::W)) {
                let mut value = timeout_limit::W(self.0.read::<0x70>());
                change(&mut value);
                self.0.write::<0x70>(value.0);
            }

            /// Read `DATE`.
            #[inline]
            pub fn read_date(&self) -> date::R {
                date::R(self.0.read::<0x1fc>())
            }

            /// Read `DATE`, change fields and write it back; every other bit keeps
            /// the value read.
            #[inline]
            pub fn modify_date(&mut self, change: impl FnOnce(&mut date::W)) {
                let mut value = date::W(self.0.read::<0x1fc>());
                change(&mut value);
                self.0.write::<0x1fc>(value.0);
            }
