        /// The `SCL_LOW_PERIOD` register.
        ///
        /// Configures the low level width of the SCL Clock
        pub mod scl_low_period {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x000001ff;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x0;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Configures the low level width of the SCL Clock in Master mode. \\ Measurement unit: I2C_SCLK \\
                #[inline]
                pub const fn scl_low_period(self) -> oer_mmio::Bits<9> {
                    oer_mmio::Bits::truncate(self.0)
                }
            }

            /// The register's value while it is changed.
            pub struct W(pub(super) u32);

            impl W {
                /// Configures the low level width of the SCL Clock in Master mode. \\ Measurement unit: I2C_SCLK \\
                #[inline]
                pub const fn scl_low_period(&self) -> oer_mmio::Bits<9> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// Set `SCL_LOW_PERIOD`.
                #[inline]
                pub fn set_scl_low_period(&mut self, value: oer_mmio::Bits<9>) -> &mut Self {
                    self.0 = (self.0 & !0x000001ff) | value.get();
                    self
                }
            }
        }

