                #[inline]
                pub const fn rx_lsb_first(self) -> bool {
                    (self.0 & 0x00000080) != 0
                }

                /// Configures whether to gate clock signal for registers.\\ 0: Support clock only when registers are read or written to by software \\ 1: Force clock on for registers \\
                #[inline]
                pub const fn clk_en(self) -> bool {
                    (self.0 & 0x00000100) != 0
                }

                /// Configures whether to enable I2C bus arbitration detection.\\ 0: No effect \\ 1: Enable \\
                #[inline]
                pub const fn arbitration_en(self) -> bool {
                    (self.0 & 0x00000200) != 0
                }

