            pub fn modify_unit1_load_hi(&mut self, change: impl FnOnce(&mut unit1_load_hi::W)) {
                let mut value = unit1_load_hi::W(self.0.read::<0x14>());
                change(&mut value);
                self.0.write::<0x14>(value.0);
            }

            /// Read `UNIT1_LOAD_LO`.
            #[inline]
            pub fn read_unit1_load_lo(&self) -> unit1_load_lo::R {
                unit1_load_lo::R(self.0.read::<0x18>())
            }

            /// Read `UNIT1_LOAD_LO`, change fields and write it back; every other bit keeps
            /// the value read.
