        /// The `ERR_CAPT_RETR_CTR_ALC_TS_INFO` register.
        ///
        /// TWAI FD error capture & retransmit counter & arbitration lost & timestamp integration information register
        pub mod err_capt_retr_ctr_alc_ts_info {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x3fff0fff;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x7c;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// 0b00000 - ERC_POS_SOF - Error in Start of Frame 0b00001 - ERC_POS_ARB - Error in Arbitration Filed 0b00010 - ERC_POS_CTRL - Error in Control field 0b00011 - ERC_POS_DATA - Error in Data Field 0b00100 - ERC_POS_CRC - Error in CRC Field 0b00101 - ERC_POS_ACK - Error in CRC delimiter, ACK field or ACK delimiter 0b00110 - ERC_POS_EOF - Error in End of frame field 0b00111 - ERC_POS_ERR - Error during Error frame 0b01000 - ERC_POS_OVRL - Error in Overload frame 0b11111 - ERC_POS_OTHER - Other position of error
                #[inline]
                pub const fn err_pos(self) -> oer_mmio::Bits<5> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// Type of last error. 0b000 - ERC_BIT_ERR - Bit Error 0b001 - ERC_CRC_ERR - CRC Error 0b010 - ERC_FRM_ERR - Form Error 0b011 - ERC_ACK_ERR - Acknowledge Error 0b100 - ERC_STUF_ERR - Stuff Error
                #[inline]
                pub const fn err_type(self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0 >> 5)
                }

                /// Current value of retransmitt counter.
                #[inline]
                pub const fn retr_ctr_val(self) -> oer_mmio::Bits<4> {
                    oer_mmio::Bits::truncate(self.0 >> 8)
                }

                /// Arbitration lost capture bit position. If ALC_ID_FIELD = ALC_BASE_ID then bit index of BASE identifier in which arbitration was lost is given as: 11 - ALC_VAL. If ALC_ID_FIELD = ALC_EXTENSION then bit index of EXTENDED identifier in which arbitration was lost is given as: 18 - ALC_VAL. For other values of ALC_ID_FIELD, this value is undefined.
                #[inline]
                pub const fn alc_bit(self) -> oer_mmio::Bits<5> {
                    oer_mmio::Bits::truncate(self.0 >> 16)
                }

                /// Part of CAN Identifier in which arbitration was lost. 0b000 - ALC_RSVD - Unit did not loose arbitration since last reset. 0b001 - ALC_BASE_ID - Arbitration was lost during base identifier. 0b010 - ALC_SRR_RTR - Arbitration was lost during first bit after base identifier (SRR of Extended Frame, RTR bit of CAN 2.0 Base Frame) 0b011 - ALC_IDE - Arbitration was lost during IDE bit. 0b100 - ALC_EXTENSION - Arbitration was lost during Identifier extension. 0b101 - ALC_RTR - Arbitration was lost during RTR bit after Identifier extension!
                #[inline]
                pub const fn alc_id_field(self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0 >> 21)
                }

                /// Number of active bits of CTU CAN FD time-base minus 1 (0x3F = 64 bit time-base).
                #[inline]
                pub const fn ts_bits(self) -> oer_mmio::Bits<6> {
                    oer_mmio::Bits::truncate(self.0 >> 24)
                }
            }
        }

